"""Authored chapter 4 companion; no raw PDF material is embedded."""
import json, math, copy
from pathlib import Path
R=Path(__file__).resolve().parents[2]
OUT=R/'stereo-course/shestakov-yaschenko-10-11/chapters/ch4.json'
L=[]; T=[]
sq=math.sqrt

def fmt(x):
 if isinstance(x,str): return x
 return str(int(x)) if abs(x-round(x))<1e-9 else str(round(x,10)).replace('.',',')
def step(title,prompt,explanation,reason,view='neutral',answer=None):
 s=dict(title=title,prompt=prompt,explanation=explanation,reason=reason,view=view)
 if answer is not None:s['input']=dict(prompt=prompt,accepted=[str(answer),str(answer).replace('.',',')],feedback='Проверь вычисление в пояснении к этому шагу.')
 return s

def prism(base,h,shift=(0,0),labels=None):
 names=list(base);p={k:[float(v[0]),float(v[1]),0] for k,v in base.items()}
 p.update({k+'1':[float(v[0]+shift[0]),float(v[1]+shift[1]),float(h)] for k,v in base.items()})
 edges=[]
 for i,k in enumerate(names):
  nxt=names[(i+1)%len(names)];edges += [[k,nxt],[k+'1',nxt+'1'],[k,k+'1']]
 faces=[names,list(reversed([k+'1' for k in names]))]+[[k,names[(i+1)%len(names)],names[(i+1)%len(names)]+'1',k+'1'] for i,k in enumerate(names)]
 return dict(points=p,edges=edges,faces=faces,labelNames=labels or list(p),views={'neutral':{'label':'Исходная призма'},'base':{'label':'Основание','polygon':names},'height':{'label':'Боковое ребро','segments':[[names[0],names[0]+'1']]}})
def tri(a,h):return prism({'A':(0,sq(3)*a/2),'B':(-a/2,0),'C':(a/2,0)},h)
def box(a,b,h):return prism({'A':(0,0),'B':(a,0),'C':(a,b),'D':(0,b)},h)
def hexagon(a,h):return prism({k:(a*math.cos(i*math.pi/3),a*math.sin(i*math.pi/3)) for i,k in enumerate('ABCDEF')},h,labels=['A','B','C','D','E','F'])
def pt(m,k,v):m['points'][k]=[float(x) for x in v]
def mid(m,k,a,b):pt(m,k,[(x+y)/2 for x,y in zip(m['points'][a],m['points'][b])])
def view(m,k,label,segments=None,polygon=None,points=None):
 m['views'][k]={'label':label}
 if segments:m['views'][k]['segments']=segments
 if polygon:m['views'][k]['polygon']=polygon
 if points:m['views'][k]['points']=points
 return k

def add(sec,level,num,part,page,title,text,goal,answer,model,steps,hint,caption=None,manual=False):
 accepted=answer if isinstance(answer,list) else [str(answer)]
 acc=[]
 for x in accepted:
  if x not in acc:acc.append(x)
  if ',' in x and x.replace(',','.') not in acc:acc.append(x.replace(',','.'))
 ans={'mode':'manual' if manual else 'exact','prompt':goal if manual else goal+' Введи '+('точное выражение в указанном ниже виде.' if any(any(c.isalpha() for c in x) for x in acc) else 'число без единицы измерения.')}
 if not manual:ans.update(accepted=acc,feedback='Ответ пока не совпал. Проверь, какой отрезок, угол или площадь требуется; затем воспользуйся подсказкой.')
 if not manual and any(any(c.isalpha() for c in x) for x in acc):ans['prompt'] += ' Для корня используй sqrt(...), для угла — arcsin(...) или arccos(...).'
 L.append(dict(section=sec,level=level,number=num,part=part,pages=page if isinstance(page,list) else [page],title=title,text=text,goal=goal,answer=ans,hint=hint,steps=steps,model=model,caption=caption or 'Поверни модель. Дополнительные отрезки выделяются на нужном шаге; по картинке длины не измеряем.'))

