# 4.6 Individual stepped bodies and skew-line configuration.
def stepped(length,depth,tallwidth,H,h):
 p={'A':[0,0,0],'B':[length,0,0],'C':[length,depth,0],'D':[0,depth,0],
    'A2':[0,0,H],'B2':[tallwidth,0,H],'C2':[tallwidth,depth,H],'D2':[0,depth,H],
    'A1':[tallwidth,0,h],'B1':[length,0,h],'C1':[length,depth,h],'D1':[tallwidth,depth,h]}
 faces=[['A','B','C','D'],['A','A2','D2','D'],['A2','B2','C2','D2'],['B2','A1','D1','C2'],['A1','B1','C1','D1'],['B','B1','C1','C'],['A','B','B1','A1','B2','A2'],['D','C','C1','D1','C2','D2']]
 edges={tuple(sorted((f[i],f[(i+1)%len(f)]))) for f in faces for i in range(len(f))}
 return {'points':p,'edges':[list(e) for e in sorted(edges)],'faces':faces,'labelNames':['A','B','C','D','A2','B2','C2','D2','B1','C1'],'views':{'neutral':{'label':'Ступенчатый многогранник'},'base':{'label':'Прямоугольное основание','polygon':['A','B','C','D']},'top':{'label':'Верхняя площадка','polygon':['A2','B2','C2','D2']}}}
for part,length,depth,width,H,drop in [('a',12,20,6,12,3),('b',18,14,9,6,3)]:
 h=H-drop;m=stepped(length,depth,width,H,h);v1=length*depth*h;v2=width*depth*drop;val=v1+v2
 add('4.6','A',25,part,130,'Объём тела с одной ступенью',f'У ступенчатого многогранника все двугранные углы прямые. По рисунку: AB={length}, A₂D₂={depth}, D₂C₂={width}, AA₂={H}, C₂D₁={drop}. Найди объём.','Найди объём многогранника.',val,m,[step('Нижняя высота','Вычти высоту ступени из полной высоты.',f'h={H}−{drop}={h}.','Полная высота складывается из высоты нижнего слоя и высоты ступени.','top',h),step('Нижний слой','Найди объём прямоугольного слоя под всей фигурой.',f'V₁={length}·{depth}·{h}={v1}.','Объём прямоугольного параллелепипеда — произведение трёх измерений.','base',v1),step('Верхняя ступень','Найди объём оставшейся верхней части.',f'V₂={width}·{depth}·{drop}={v2}.','Верхняя ступень — прямоугольный параллелепипед.','top',v2),step('Сложи без пересечения','Слои имеют общую границу, но не общий объём.',f'V={v1}+{v2}={val}.','Объёмы тел с непересекающимися внутренностями складываются.','top',val)],'Разрежь фигуру горизонтальной плоскостью по уровню нижней площадки.',caption='Модель восстановлена по рисунку №A25, стр. 130. Подписи длин вынесены в условие; фигура сохраняет заданные пропорции.')
for part,width,depth,H,drop,front in [('a',3,3,4,2,2),('b',3,5,3,2,2)]:
 h=H-drop;tall=depth-front;m=stepped(depth,width,tall,H,h);m['labelNames']=[];v1=width*depth*h;v2=width*tall*drop;v=v1+v2
 add('4.6','A',26,part,130,'Два прямоугольных слоя',f'У ступенчатого многогранника все двугранные углы прямые. Ширина {width}, полная глубина {depth}, полная высота {H}, перепад между площадками {drop}, глубина нижней открытой площадки {front}. Найди объём.','Найди объём.',v,m,[step('Две недостающие длины','Найди нижнюю высоту и глубину верхней части.',f'Нижняя высота {H}−{drop}={h}; глубина верхней части {depth}−{front}={tall}.','Общая длина равна сумме частей.','top'),step('Нижний слой','Умножь ширину, полную глубину и нижнюю высоту.',f'V₁={width}·{depth}·{h}={v1}.','Формула объёма прямоугольного параллелепипеда.','base',v1),step('Верхний слой','Верхний слой занимает лишь часть глубины.',f'V₂={width}·{tall}·{drop}={v2}; V={v1}+{v2}={v}.','Объём складывается из непересекающихся слоёв.','top',v)],'Число у вертикальной ступени — перепад высот, а не высота нижнего слоя.',caption='Форма и все размеры восстановлены по рисунку №A26, стр. 130. Верхняя площадка показана слева при исходном ракурсе; модель можно повернуть.')
for part,w,d,h,nw,nd in [('a',5,4,3,2,2),('b',3,5,2,1,2)]:
 base={'A':(0,0),'B':(w-nw,0),'C':(w-nw,nd),'D':(w,nd),'E':(w,d),'F':(0,d)};m=prism(base,h,labels=['A','B','C','D','E','F']);val=(w*d-nw*nd)*h
 add('4.6','A',27,part,130,'Объём тела с прямоугольной выемкой',f'Все двугранные углы многогранника прямые. Внешний параллелепипед имеет ширину {w}, глубину {d}, высоту {h}. В переднем правом углу вырезана часть шириной {nw} и глубиной {nd} на всю высоту. Найди объём оставшегося тела.','Найди объём оставшегося тела.',val,m,[step('Объём целого','Мысленно дострой выемку.',f'Vцел={w}·{d}·{h}={w*d*h}.','Прямоугольный параллелепипед имеет объём abc.','base',w*d*h),step('Объём выемки','Высота выемки совпадает с высотой тела.',f'Vвыр={nw}·{nd}·{h}={nw*nd*h}.','Вырезанная часть также прямоугольный параллелепипед.','height',nw*nd*h),step('Остаток','Вычти объём отсутствующей части.',f'V={w*d*h}−{nw*nd*h}={val}.','Аддитивность объёма: целое состоит из оставшейся и вырезанной частей.','base',val)],'Удобнее достроить тело до параллелепипеда, затем вычесть выемку.',caption='Г-образное основание и размеры восстановлены по рисунку №A27, стр. 130. Буквы введены в курсе для управления моделью.')
for part,a in [('a',5),('b',7)]:
 b=2*a;p={'A':[0,0,0],'B':[a,0,0],'C':[a,b,0],'D':[0,b,0],'D1':[0,b/2,b*sq(3)/2],'C1':[a,b/2,b*sq(3)/2],'D2':[0,-b/2,b*sq(3)/2],'C2':[a,-b/2,b*sq(3)/2]};m={'points':p,'edges':[['A','B'],['B','C'],['C','D'],['D','A'],['B','C1'],['C1','D1'],['D1','A']],'faces':[['A','B','C','D'],['A','B','C1','D1']],'labelNames':['A','B','C','D','C1','D1'],'views':{'neutral':{'label':'Один допустимый вариант расположения'},'first':{'label':'Угол между полуплоскостями 60°','segments':[['A','C'],['B','D1']]},'second':{'label':'Другой допустимый вариант: 120°','segments':[['A','C'],['B','D2']],'polygon':['A','B','C2','D2']}}}
 add('4.6','B',2,part,135,'Угол: проверка достаточности условия',f'Два равных прямоугольника ABCD и ABC₁D₁ имеют общую сторону AB. Угол между их плоскостями равен 60°. AB={a}, AD={b}. Найди угол между AC и BD₁.','Запиши возможные углы и объясни, какое уточнение расположения прямоугольников требуется.',[],m,[step('Проверь условие','Определяет ли угол плоскостей сторону расположения D₁?','Нет. Острый угол между плоскостями 60° совместим с углом между лучами AD и AD₁ как 60°, так и 120°. В тексте книги дополнительное расположение не задано.','Плоскость содержит две полуплоскости относительно общей прямой AB.','first'),step('Первое расположение','Пусть угол между AD и AD₁ равен 60°.','При AB=a, AD=2a: AC=(a;2a;0), BD₁=(−a;a;a√3). Их скалярное произведение a², произведение длин 5a². Получаем φ=arccos(1/5).','Угол между прямыми определяется абсолютным скалярным произведением направляющих векторов.','first'),step('Второе расположение','Пусть угол между AD и AD₁ равен 120°.','Теперь BD₁=(−a;−a;a√3); скалярное произведение с AC равно −3a². Для угла между прямыми берём модуль: φ=arccos(3/5).','Угол между прямыми выбирают не больше 90°; нужен модуль косинуса.','second'),step('Корректный итог','Что нужно указать в ответе к такой формулировке?','Возможны arccos(1/5) и arccos(3/5). Единственный численный ответ появляется после уточнения, какой угол образуют полуплоскости прямоугольников.','Показаны две конфигурации, удовлетворяющие всем явно заданным условиям.','second')],'Не подменяй угол между бесконечными плоскостями углом между конкретными лучами.',manual=True,caption='В книге у №B2 нет рисунка. Исходная модель показывает угол 60° между полуплоскостями; второй вид показывает другое допустимое расположение. Ответ требует обсуждения, автоматической оценки нет.')
for part,aa,bb,c2,q2,h,qs in [('a',5,7,35/100,3/40,1,'√(3/40)'),('b',3,5,15/100,4/15,2,'2√15/15')]:
 a,b,c=sq(aa),sq(bb),sq(c2);ss=sq(1-c2);p={'E':[0,0,0],'P':[0,0,h],'A':[-a,0,0],'B':[a,0,0],'C':[b*c,b*ss,h],'D':[-b*c,-b*ss,h]};m={'points':p,'edges':[['A','B'],['C','D'],['E','P']],'labelNames':['A','B','C','D','E','P'],'views':{'neutral':{'label':'Две скрещивающиеся прямые и общий перпендикуляр'},'angle':{'label':'Угол ACB','segments':[['A','C'],['C','B']]},'perp':{'label':'Общий перпендикуляр EP','segments':[['E','P']]}}};coef=round(4*aa*bb*c2);poly='37t²+88t−125=0' if part=='a' else '11t²−4t−160=0';factor='(t−1)(37t+125)=0' if part=='a' else '(t−4)(11t+40)=0'
 add('4.6','C',1,part,135,'Расстояние между скрещивающимися прямыми',f'E и P — середины AB и CD; эти отрезки лежат на скрещивающихся прямых. EP — их общий перпендикуляр. AB=2√{aa}, CD=2√{bb}, косинус угла между прямыми равен √{round(c2*100)}/10. cos∠ACB={qs}. Найди EP.','Найди длину EP.',h,m,[step('Обозначь неизвестную длину','Пусть EP=H>0 и t=H².','Поместим E в начало координат, AB вдоль x, EP вдоль z. A=(−a;0;0), B=(a;0;0), C=(bc;b√(1−c²);H), где a=AB/2, b=CD/2, c — косинус угла прямых. Знак c не влияет на дальнейшие квадраты.','Общий перпендикуляр ортогонален обоим направлениям прямых.','perp'),step('Косинус угла ACB','Вычисли скалярное произведение CA и CB.',f'CA·CB=t+b²−a²=t+{bb-aa}. Произведение квадратов длин: |CA|²|CB|²=(t+a²+b²)²−4a²b²c²=(t+{aa+bb})²−{coef}.','Формула скалярного произведения и разность квадратов.','angle'),step('Уравнение','Возведи известный косинус в квадрат.',f'(t+{bb-aa})²/((t+{aa+bb})²−{coef})='+('3/40' if part=='a' else '4/15')+f'. После умножения: {poly}; {factor}.','При положительных длинах знаменатель положителен; подставлены исходные a², b², c².','angle'),step('Выбери допустимый корень','t — квадрат положительной длины.',f'Из двух корней допустим t={h*h}. Поэтому EP=√{h*h}={h}. Подстановка в исходную формулу даёт положительный заданный косинус.','Отрицательный корень t невозможен; проверка устраняет риск постороннего решения после возведения в квадрат.','perp',h)],'Используй середины как начала симметричных координат: тогда скалярное произведение сильно упростится.',caption='Координаты модели рассчитаны из условий задачи, включая заданный косинус ∠ACB. Общий перпендикуляр выделен отдельно.')

# Authored theory companions. Each is a support lesson, not a transcription of a nonexistent textbook theory paragraph.
def theory(sec,title,page,text,goal,model,steps,hint):
 T.append(dict(section=sec,title=title,pages=[page],text=text,goal=goal,model=model,steps=steps,hint=hint,caption='Авторское объяснение к задачам раздела. Меняй ракурс; дополнительные отрезки появляются при выборе шага.'))
m=tri(4,5)
for k,u,v in [('M','A','B'),('N','A','C'),('M1','A1','B1'),('N1','A1','C1')]:mid(m,k,u,v)
view(m,'section','Сечение через среднюю линию',polygon=['M','N','N1','M1'])
theory('4.1','Призма: основание, высота, сечение',83,'У призмы два равных параллельных основания. В прямой призме боковые рёбра перпендикулярны основаниям. Правильная призма — прямая призма с правильным многоугольником в основании.','Различай высоту и боковое ребро, выбирай формулы площади и объёма.',m,[step('Определи основание','Какие два многоугольника получаются переносом?','ABC и A₁B₁C₁ — равные параллельные треугольники. Боковые рёбра AA₁, BB₁, CC₁ параллельны и равны.','Определение призмы.','base'),step('Найди высоту','В каком случае высота равна боковому ребру?','Только у прямой призмы боковое ребро перпендикулярно основанию. У наклонной призмы при ребре l и угле α с основанием высота h=l·sin α.','Высота — расстояние между параллельными плоскостями.','height'),step('Выбери формулу','Нужен объём или поверхность?','V=Sосн·h для любой призмы. Для прямой призмы Sбок=Pосн·h. Полная поверхность Sполн=2Sосн+Sбок.','Разбиение на слои для объёма; прямоугольная развёртка для боковой поверхности.','height'),step('Ищи сечение','Как провести плоскость через середины AB и AC параллельно боковым рёбрам?','Соедини середины M,N; проведи MM₁ и NN₁ параллельно AA₁. У прямой призмы получишь прямоугольник MN N₁ M₁ шириной BC/2 и высотой h.','Средняя линия треугольника; пересечения параллельных плоскостей третьей плоскостью параллельны.','section')],'Сначала назови основание и найди перпендикулярную ему высоту.')
m=box(3,3,3);view(m,'diag','Две разные диагонали',segments=[['A','C'],['A','C1']])
theory('4.2','Куб: диагонали, масштаб и координаты',97,'У куба все шесть граней — равные квадраты. Диагональ грани и пространственная диагональ — разные отрезки.','Выводи dграни=a√2, dкуба=a√3; решай задачи на масштаб и взаимное положение.',m,[step('Диагональ грани','Рассмотри прямоугольный треугольник ABC.','AC²=a²+a²=2a², поэтому AC=a√2.','Теорема Пифагора в квадрате.','diag'),step('Пространственная диагональ','Добавь перпендикулярное боковое ребро.','AC₁²=AC²+CC₁²=2a²+a²=3a², поэтому AC₁=a√3.','Теорема Пифагора в диагональном сечении.','diag'),step('Площадь и объём','Как изменятся величины при увеличении ребра в k раз?','S=6a² и V=a³. После увеличения всех рёбер в k раз площадь умножится на k², объём — на k³.','Площадь имеет две линейные размерности, объём — три.','base'),step('Углы и расстояния','Возьми три ребра из A за координатные оси.','A=(0;0;0), B=(a;0;0), D=(0;a;0), A₁=(0;0;a). Остальные координаты получаются сложением соответствующих векторов; середины — полусуммами координат.','Рёбра куба из одной вершины взаимно перпендикулярны.','height')],'Диагональ грани соединяет вершины одной грани; пространственная диагональ проходит через внутренность куба.')
m=box(4,3,5);view(m,'diag','Диагональное сечение',polygon=['A','C','C1','A1'])
theory('4.3','Прямоугольный параллелепипед: три измерения',104,'Прямоугольный параллелепипед задаётся тремя попарно перпендикулярными рёбрами a, b, h. Для его диагонали нужны все три измерения.','Выбирай формулу по искомой величине и находи нужный прямоугольный треугольник.',m,[step('Диагональ','Сначала основание, затем пространственный отрезок.','d²=a²+b²+h². Например, при a=4,b=3,h=5 диагональ основания равна 5, пространственная — 5√2.','Дважды применённая теорема Пифагора.','diag'),step('Поверхность','Посчитай три вида граней и удвой.','Sполн=2(ab+ah+bh). На модели: 2(12+20+15)=94.','Каждая из трёх разных прямоугольных граней имеет равную противоположную.','base'),step('Объём','Умножь площадь основания на высоту.','V=abh; на модели V=4·3·5=60.','Объём прямой призмы равен Sосн·h.','height'),step('Не спутай угол','Каким отрезком задаётся проекция пространственной диагонали?','Проекция AC₁ на основание — AC. Поэтому угол диагонали с основанием равен ∠CAC₁, и tg∠CAC₁=h/√(a²+b²).','Определение угла прямой и плоскости; ортогональная проекция.','diag')],'Нарисуй диагональное сечение: пространственная задача часто превращается в прямоугольный треугольник.')
m=rhomb(8,6,4);view(m,'diagonals','Диагонали ромба',segments=[['A','C'],['B','D']])
theory('4.4','Ромб в основании и наклонные рёбра',114,'У прямого параллелепипеда основание может быть любым параллелограммом. Прямой не означает прямоугольный: ромб в основании не обязан быть квадратом.','Находи площадь и периметр ромба; отличай высоту от наклонного бокового ребра.',m,[step('Диагонали ромба','Какие два свойства дают прямоугольный треугольник?','Диагонали ромба перпендикулярны и делятся пополам. При d₁=8,d₂=6 сторона a=√(4²+3²)=5.','Свойства диагоналей ромба и теорема Пифагора.','diagonals'),step('Площадь и периметр','Не подменяй площадь произведением диагоналей.','Sосн=d₁d₂/2=24, P=4a=20. Если даны сторона и угол α, Sосн=a² sin α.','Формулы площади ромба и параллелограмма.','base'),step('Полная поверхность прямого тела','Добавь два основания и боковую поверхность.','При h=4: Sполн=2·24+20·4=128.','Для прямой призмы Sбок=Pосн·h.','height'),step('Наклонное тело','Какая формула остаётся верной при наклоне?','V=Sосн·h остаётся верной, но h — перпендикулярное расстояние между основаниями. Если задано наклонное ребро l и его угол β с основанием, h=l sin β.','Определение высоты и синуса в прямоугольном треугольнике.','height')],'Слово «прямой» относится к боковым рёбрам, а не к углам ромба.')
m=hexagon(2,3);pt(m,'O',[0,0,0]);view(m,'radii','Шесть равносторонних треугольников',segments=[['O',k] for k in 'ABCDEF'],points=['O']);view(m,'diagonals','Две разные диагонали',segments=[['A','C'],['A','D']])
theory('4.5','Правильный шестиугольник внутри призмы',116,'Правильный шестиугольник делится на шесть равносторонних треугольников. Это даёт сразу площадь, две длины диагоналей и удобные координаты.','Узнавай короткую и большую диагонали; используй свойства основания в пространстве.',m,[step('Радиус и сторона','Соедини центр O с соседними вершинами.','Центральный угол равен 360°/6=60°. Треугольник OAB равносторонний, поэтому OA=AB=a.','Равные радиусы и угол 60° образуют равносторонний треугольник.','radii'),step('Две диагонали','Сравни AC и AD.','AC=a√3 — короткая диагональ; AD=2a — большая диагональ между противоположными вершинами.','Формула хорды 2a sin60° и диаметр описанной окружности.','diagonals'),step('Площадь основания','Сложи шесть треугольников.','Sосн=6·a²√3/4=3a²√3/2. Периметр P=6a.','Площадь равностороннего треугольника.','radii'),step('Призма','Что добавляет высота h?','V=(3a²√3/2)h, Sбок=6ah. Для пространственного отрезка между разными основаниями: d²=dпроекции²+h².','Формулы призмы и теорема Пифагора.','height')],'Не считай любую диагональ шестиугольника равной 2a: это верно только для противоположных вершин.')
m=stepped(5,4,3,4,2)
theory('4.6','Многогранник: разбиение, выемки и расстояния',119,'Сложное тело можно разбить на простые части или достроить до параллелепипеда. Для угла и расстояния сначала выдели нужную плоскую фигуру или выбери координаты.','Разбивай объём без двойного счёта; проверяй, достаточно ли условий для ответа.',m,[step('Прочитай размеры','Отдели полную высоту от перепада площадок.','На примере: полная высота 4, перепад 2, нижняя высота 4−2=2. Полная ширина 5, верхняя ширина 3, глубина 4.','Смежные отрезки на одной прямой складываются.','top'),step('Два слоя','Посчитай части, которые не перекрываются по объёму.','Нижний слой: 5·4·2=40. Верхняя ступень: 3·4·2=24. Общий объём 64.','Аддитивность объёма для частей с непересекающимися внутренностями.','base'),step('Проверка достраиванием','Дострой тело до целого параллелепипеда.','Объём полного тела 5·4·4=80. Выемка: (5−3)·4·2=16. Разность 80−16=64 совпала.','Целое состоит из оставшейся части и выемки.','top'),step('Расстояние и угол','Можно ли просто измерить линию на экране?','Нет. Для расстояния нужен перпендикуляр; для тангенса — верный прямоугольный треугольник. Если разные конфигурации удовлетворяют условию и дают разные ответы, следует указать недостающее условие.','Определение расстояния; рисунок служит моделью, но не заменяет доказательство.','neutral')],'Сначала найди простую структуру тела: слои, одинаковые призмы или отсутствующий прямоугольный кусок.')

# Replace the misprinted A1 pair with the fully determined A28 pair (PDF p.131).
for part,w,d,H,low,cw,cd in [('a',4,4,5,3,2,2),('b',5,4,3,2,2,2)]:
 p={'A':[0,0,0],'B':[w,0,0],'C':[w,d,0],'D':[0,d,0],
    'E':[0,0,low],'F':[cw,0,low],'G':[cw,cd,low],'H':[0,cd,low],
    'I':[cw,0,H],'J':[w,0,H],'K':[w,d,H],'L':[0,d,H],'M':[0,cd,H],'N':[cw,cd,H]}
 faces=[['A','B','C','D'],['A','B','J','I','F','E'],['A','D','L','M','H','E'],['B','C','K','J'],['D','C','K','L'],['I','J','K','L','M','N'],['E','F','G','H'],['F','I','N','G'],['H','M','N','G']]
 edges={tuple(sorted((f[i],f[(i+1)%len(f)]))) for f in faces for i in range(len(f))}
 m={'points':p,'edges':[list(e) for e in sorted(edges)],'faces':faces,'labelNames':['A','B','C','D'],'views':{'neutral':{'label':'Параллелепипед с выемкой сверху'},'base':{'label':'Полное основание','polygon':['A','B','C','D']},'notch':{'label':'Нижняя площадка выемки','polygon':['E','F','G','H'],'segments':[['F','I'],['H','M']]}}}
 full=w*d*H;cut=cw*cd*(H-low);val=full-cut
 add('4.6','A',28,part,131,'Выемка в верхнем углу',f'Все двугранные углы многогранника прямые. По рисунку полная ширина {w}, глубина {d}, высота {H}. В верхнем переднем левом углу сделана прямоугольная выемка шириной {cw}, глубиной {cd}; высота её нижней площадки над основанием равна {low}. Найди объём оставшегося тела.','Найди объём оставшегося тела.',val,m,[step('Полный параллелепипед','Мысленно заполни выемку.',f'Vцел={w}·{d}·{H}={full}.','Объём прямоугольного параллелепипеда равен произведению трёх измерений.','base',full),step('Высота выемки','Вычти высоту нижней площадки из полной высоты.',f'hвыр={H}−{low}={H-low}.','Смежные вертикальные отрезки складываются.','notch',H-low),step('Вырезанная часть','Умножь три размера выемки.',f'Vвыр={cw}·{cd}·{H-low}={cut}.','Выемка имеет форму прямоугольного параллелепипеда.','notch',cut),step('Оставшееся тело','Вычти выемку из полного объёма.',f'V={full}−{cut}={val}.','Аддитивность объёма.','notch',val)],'Размер у нижней площадки — её высота над основанием. Высоту вырезанной части нужно найти вычитанием.',caption='Форма и все размеры восстановлены по рисунку №A28, стр. 131. Буквы A–D введены в курсе; подписи размеров вынесены в условие.')

# Initial scene audit: show source-given objects, hide only auxiliary constructions.
def initial(card,points=(),segments=(),labels=None):
 m=card['model']
 if labels is not None:m['labelNames']=list(labels)
 else:m['labelNames']=list(dict.fromkeys(m.get('labelNames',[])+list(points)))
 known={tuple(sorted(e)) for e in m['edges']}
 for edge in segments:
  if tuple(sorted(edge)) not in known:
   m['edges'].append(list(edge));known.add(tuple(sorted(edge)))
 m['views']['neutral']['label']='Дано в условии: исходная фигура и отмеченные объекты'
 if points:m['views']['neutral']['points']=list(points)

for card in L:
 sec,lev,num,part=card['section'],card['level'],card['number'],card['part']
 if sec=='4.1':
  if lev=='A' and num==1:initial(card,segments=[['B' if part=='a' else 'C','A1']])
  elif lev=='A' and num==18:
   initial(card,points=['M','N','M1','N1'],segments=[['M','N'],['N','N1'],['N1','M1'],['M1','M']])
   card['model']['views']['neutral']['polygon']=['M','N','N1','M1']
  elif lev=='B' and num in (1,2):
   names=['M']+(['K' if part=='a' else 'P'] if num==2 else [])
   initial(card,points=names,segments=[['B','M'],['M','C']])
  elif lev=='C' and num==1:
   initial(card,points=['M','E','F' if part=='a' else 'O'],segments=[['B','M'],['M','E'],['E','B']]+([['B','C1'],['B1','C']] if part=='b' else []))
 elif sec=='4.2':
  if lev=='A' and num==1:initial(card,segments=[['B','C1']] if part=='a' else [['B','A1'],['D','C1']])
  elif lev=='A' and num==10:initial(card,segments=[['A','C1']])
  elif lev=='B' and num==1:initial(card,points=['M','N','E'],segments=[['A','M'],['M','N'],['N','A']])
  elif lev=='B' and num==4:initial(card,points=['M','N'],segments=[['D1','M'],['M','N'],['N','D1']])
  elif lev=='C' and num==2:initial(card,points=['P' if part=='a' else 'F'],segments=[['A','D1'],['D1','B1'],['B1','A']]+([['B','C1'],['B1','C']] if part=='b' else []))
 elif sec=='4.3':
  if lev=='A' and num==9:initial(card,segments=[['A1','C']] if part=='a' else [['B','D1']])
  elif lev=='A' and num==12:initial(card,segments=[['A','C1'],['B','D'],['B1','D']] if part=='a' else [['B','D1'],['A','C'],['A1','C']])
  elif lev=='B' and num==1:initial(card,segments=[['A','B1'],['B1','D1'],['D1','A']])
  elif lev=='B' and num==4:initial(card,points=['E','T'],segments=[['E','T'],['T','D1'],['D1','E']])
  elif lev=='C' and num==1:initial(card,segments=[['B','D'],['D','A1'],['A1','B']])
 elif sec=='4.4':
  if lev=='A' and num in (2,3):initial(card,segments=[['A','C'],['B','D']])
  elif lev=='B' and num==1:initial(card,segments=[['A1','D']])
  elif lev=='C' and num==2:
   initial(card,points=['O','K'],segments=[['B','O'],['D1','A']] if part=='a' else [['B1','O'],['D','A1']])
   m=card['model'];m['points']['_u']=list(m['points']['U']);m['points']['_v']=list(m['points']['V'])
   m['views']['neutral']['polygon']=['K','_u','_v']
 elif sec=='4.5':
  if lev=='A' and num==1:initial(card,points=['E1'] if part=='a' else ['D1'],segments=[['B','E1'],['B','E']] if part=='a' else [['A','D'],['A','D1']])
  elif lev=='B' and num==4:initial(card,points=['F1'] if part=='a' else ['E1'],segments=[['D','F1']] if part=='a' else [['A','E1']])
  elif lev=='B' and num==6:
   names=['A','C','E'] if part=='a' else ['B','C','E'];tops=[n+'1' for n in names]
   initial(card,points=tops,segments=[[names[i],names[(i+1)%3]] for i in range(3)]+[[tops[i],tops[(i+1)%3]] for i in range(3)])
  elif lev=='C' and num==1:initial(card,points=['M','B1','F1']+(['D1'] if part=='a' else []),segments=[['M','B1'],['B1','F1'],['F1','M']])
 elif sec=='4.6':
  if lev=='A' and num==25:initial(card,labels=['A','B','A2','D2','C2','D1'])
  elif lev=='B' and num==2:initial(card,segments=[['A','C'],['B','D1']])
  elif lev=='C' and num==1:initial(card,segments=[['A','C'],['C','B']])

# Normalize numeric literals, verify basic authoring invariants.
for card in L:
 if card['answer']['mode']=='exact':
  vals=card['answer']['accepted'];clean=[]
  for val in vals:
   try:
    f=float(val.replace(',','.'))
    if f.is_integer():val=str(int(f))
   except ValueError:pass
   if val not in clean:clean.append(val)
  card['answer']['accepted']=clean
assert len(L)==72, len(L)
assert len(T)==6
assert len({(x['section'],x['level'],x['number'],x['part']) for x in L})==72
for x in L+T:
 assert len(x['steps'])>=3
 assert all(s['view'] in x['model']['views'] for s in x['steps'])
 for p in x['model']['points'].values():assert len(p)==3 and all(math.isfinite(q) for q in p)
OUT.write_text(json.dumps({'chapter':4,'title':'Прямые, плоскости, призмы','theory':T,'lessons':L,'authorNotes':['72 variants across all six subsections; selection is not the complete chapter.','Section 4.6 B2 source lacks a half-plane orientation condition; both valid angles are explained and answer is manual.','Section 4.6 figure-based A25/A26/A27/A28 were checked against rendered PDF pages 130/131; misprinted A1 was excluded.']},ensure_ascii=False,indent=2)+'\n')
print(f'Wrote {len(L)} exercises and {len(T)} theory cards')
